package com.iingstd.photoprint;
import android.app.*;import android.os.*;import android.widget.*;import android.graphics.Color;import java.net.*;import java.io.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,64,32,32);setContentView(l); TextView title=new TextView(this);title.setText("IING STD Photo Print");title.setTextSize(26);title.setTextColor(0xff007f80);l.addView(title); EditText uri=new EditText(this);uri.setHint("ipp://192.168.1.100:631/ipp/print");uri.setText(getPreferences(0).getString("uri",""));l.addView(uri);Button probe=new Button(this);probe.setText("Uji koneksi printer IPP");l.addView(probe);TextView status=new TextView(this);l.addView(status);probe.setOnClickListener(v->{String s=uri.getText().toString().trim();getPreferences(0).edit().putString("uri",s).apply();status.setText("Memeriksa printer...");probe.setEnabled(false);new Thread(()->{String result;try{result=Ipp.probe(s);}catch(Exception e){result="Gagal: "+e.getMessage();}String r=result;runOnUiThread(()->{status.setText(r);probe.setEnabled(true);});}).start();}); }
}
